function terrainControl(row){
  if(!row?.kind?.startsWith('terrain-conditioning-')||row.state==='unreadable'||
     !/^[0-9a-f]{64}$/.test(row?.id||'')||typeof host.openDesk!=='function')return '';
  const response=['terrain-conditioning-responses','terrain-conditioning-report-sources'].includes(row.kind);
